/* AI-only Damnd arena, recovered Final Fight Slum boss courtyard (stage0 section2).
   Source: mysticalg/final-fight-web-playtest 5ec2d8c0c6e1465c2281d390a32e022126ff0ec9.
   Native flat courtyard x2408..3128; original chunk planeY0. No generated scenery. */
'use strict';
window.SF2AIDamndStage=(()=>{
 const main=new Image(),far=new Image();main.src='data:image/png;base64,';far.src='data:image/png;base64,';
 const ready=Promise.all([main.decode(),far.decode()]);
 const width=720;
 function draw(ctx,camera,viewWidth,top,height,ground){if(window.SF2?.G.AIFinisherTravel){const y=ground-206,bottom=top+height,cam=((camera%width)+width)%width;ctx.save();ctx.imageSmoothingEnabled=false;ctx.fillStyle='#6699cc';ctx.fillRect(0,top,viewWidth,height);for(let x=-((camera*.25)%far.naturalWidth)-far.naturalWidth;x<viewWidth;x+=far.naturalWidth)ctx.drawImage(far,x,y-32);for(let x=-cam;x<viewWidth;x+=width){for(let dy=y+240;dy<bottom;dy+=16)ctx.drawImage(main,0,224,720,16,x,dy,720,16);for(let dy=top;dy<y;dy+=16)for(let wx=392;wx<720;wx+=32)ctx.drawImage(main,624,32,32,16,x+wx,dy,Math.min(32,720-wx),16);ctx.drawImage(main,x,y);}ctx.restore();return;}
  // The recovered floor is rigidly registered to actor world coordinates.
  // Only the distant Metro City skyline has quarter-speed parallax.
  const y=ground-206,bottom=top+height;
  ctx.save();ctx.imageSmoothingEnabled=false;ctx.filter='none';ctx.fillStyle='#6699cc';ctx.fillRect(0,top,viewWidth,height);
  for(let x=-((camera*.25)%far.naturalWidth)-far.naturalWidth;x<viewWidth;x+=far.naturalWidth)ctx.drawImage(far,x,y-32);
  for(let dy=y+240;dy<bottom;dy+=16)ctx.drawImage(main,0,224,720,16,-camera,dy,720,16);
  // Extend the offscreen brick wall with its own native masonry tile, so
  // zooming out never exposes a clipped building edge against the sky.
  for(let dy=top;dy<y;dy+=16)for(let wx=392;wx<720;wx+=32)ctx.drawImage(main,624,32,32,16,wx-camera,dy,Math.min(32,720-wx),16);
  ctx.drawImage(main,-camera,y);ctx.restore();
 }
 return{ready,width,draw,name:'Damnd: Slum Courtyard'};
})();
